                        bit_count <= 3'b0;
                    end
                end

                DATA: begin
                    data_reg[bit_count] <= in;
                    if (bit_count == 3'd7) begin
                        state <= STOP;
                    end else begin
                        bit_count <= bit_count + 3'd1;
                    end
                end

                STOP: begin
                    if (in) begin
                        out_byte <= data_reg;
                        done     <= 1'b1;
                        state    <= IDLE;
                    end
                end

                default: begin
                    state     <= IDLE;
                    data_reg  <= 8'b0;
                    bit_count <= 3'b0;
                end
            endcase
        end
    end

endmodule
